def transform(grid):
    out = [row[:] for row in grid]
    p = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v in (1, 2):
                p[v] = (r, c)

    r, c = p[1]
    tr, tc = p[2]
    dr = 1 if tr > r else -1
    dc = 1 if tc > c else -1

    # End one cell above/below and one cell left/right of the 2.
    er, ec = tr - dr, tc - dc

    while r != er and c != ec:
        r += dr
        c += dc
        out[r][c] = 3
    while r != er:
        r += dr
        out[r][c] = 3
    while c != ec:
        c += dc
        out[r][c] = 3
    return out
